   "id": "base-board-perspectives-wish-14",
   "kind": "wish",
   "role": "Alle",
   "audience": "pair",
   "text": "Finn et vanlig måltid der dere vil sammenligne hva som gjør det hyggelig, før dere endrer noe.",
