   "id": "base-board-perspectives-wish-29",
   "kind": "wish",
   "role": "Alle",
   "audience": "pair",
   "text": "Planlegg å se på en kjent utsikt fra et litt annet sted uten å gjøre turen lengre.",
   "pack": "Nye perspektiver",
